changes=[]
def diff(a,b,path=''):
 if type(a)!=type(b):return [{'path':path,'before':a,'after':b}]
 if isinstance(a,dict):
  z=[]
  for k in sorted(set(a)|set(b)):
   if k not in a:z.append({'path':path+'/'+k,'beforeAbsent':True,'after':b[k]})
   elif k not in b:z.append({'path':path+'/'+k,'before':a[k],'afterAbsent':True})
   else:z+=diff(a[k],b[k],path+'/'+k)
  return z
 if isinstance(a,list):
  z=[]
  for i in range(max(len(a),len(b))):
   if i>=len(a):z.append({'path':path+'/'+str(i),'beforeAbsent':True,'after':b[i]})
   elif i>=len(b):z.append({'path':path+'/'+str(i),'before':a[i],'afterAbsent':True})
   else:z+=diff(a[i],b[i],path+'/'+str(i))
  return z
 return [] if a==b else [{'path':path,'before':a,'after':b}]
for b,a in zip(before,after):changes.append({'goalId':b['goalId'],'profileDeltas':diff(b['profile'],a['profile'])})
write('candidate/BEFORE-AFTER.exact-profile-deltas.author.json',{'schemaVersion':1,'boundary':'Author text delta only; no scientific approval implied','goals':changes})
